INSERT INTO ambito (id, codigo_regra, nome, descricao) VALUES
(1,'R01','Relacionamentos','Dicionário R: interpretações voltadas a vínculos afetivos e familiares.'),
(2,'R02','Profissional','Dicionário P: interpretações voltadas a carreira, trabalho e projetos.'),
(3,'R03','Acadêmico','Dicionário A: interpretações voltadas a estudos, provas e formação.');
INSERT INTO posicao (id, codigo_regra, nome, descricao) VALUES
(1,'R04','Significador','Representa a situação/pessoa no momento presente.'),
(2,'R05','Movimento','Representa a ação ou tendência em curso.'),
(3,'R06','Resultado','Representa o desfecho provável se a tendência atual continuar.');
INSERT INTO tipo_tiragem (id, codigo_regra, nome, qtd_cartas, descricao) VALUES
(1,'R27','1 carta',1,'Visão geral: Significador.'),
(2,'R28','2 cartas',2,'Situação → tendência: Significador e Movimento.'),
(3,'R29','3 cartas',3,'Situação → movimento → resultado.');
INSERT INTO tipo_tiragem_posicao (tipo_tiragem_id, posicao_id, ordem) VALUES
(1,1,1), (2,1,1),(2,2,2), (3,1,1),(3,2,2),(3,3,3);
INSERT INTO categoria_resultado (id, codigo, nome, descricao) VALUES
(1,'FAVORAVEL','Favorável','O cenário tende a um desfecho positivo, alinhado ao que o consulente busca.'),
(2,'CAUTELA','Cautela / Adiar','Momento não é ideal para decisões definitivas; recomenda-se esperar ou reunir mais informações antes de agir.'),
(3,'MUDANCA','Mudança Necessária','O cenário exige uma ruptura ou mudança de rota para evoluir.'),
(4,'NEUTRO','Neutro / Mais Informação','As cartas não indicam claramente um desfecho; recomenda-se nova tiragem ou reflexão adicional.');
INSERT INTO fato (codigo, pergunta, fonte) VALUES
('HISTORICO_SOLIDO', 'Você considera que seu histórico/esforço nesta situação é sólido — que você fez a sua parte?', 'R13 / ficha 9.3.7: A Justiça é Favorável se o histórico for sólido; caso contrário, Mudança Necessária.');
INSERT INTO carta (id, nome, numero_arcano, numeral, codigo_regra, aprofundada, descricao_geral, categoria_sugerida_id, fato_codigo, categoria_se_falso_id, nuance_categoria) VALUES
(1, 'O Louco', 0, '0', 'R07', TRUE, 'Arquétipo do início absoluto: potencial puro ainda não testado pela realidade. Representa fé no desconhecido, coragem e espontaneidade — mas também a sombra da imprudência se agir sem nenhum discernimento.', 4, NULL, NULL, NULL),
(2, 'O Mago', 1, 'I', 'R08', TRUE, 'Manifestação e poder pessoal: ter as ferramentas necessárias (os 4 naipes na mesa) e usar a vontade e o foco para transformar potencial em realidade concreta.', 1, NULL, NULL, 'quando combinado com ação real'),
(3, 'A Sacerdotisa', 2, 'II', 'R09', TRUE, 'Intuição, mistério e conhecimento interior ainda não revelado. Representa o inconsciente, a espera consciente e a confiança na percepção interna, mesmo sem prova lógica.', 4, NULL, NULL, NULL),
(4, 'A Imperatriz', 3, 'III', NULL, FALSE, 'Abundância, fertilidade, criatividade e cuidado — crescimento natural de algo que está sendo bem nutrido.', 1, NULL, NULL, NULL),
(5, 'O Imperador', 4, 'IV', NULL, FALSE, 'Estrutura, autoridade e ordem — liderança prática e construção de bases sólidas.', 4, NULL, NULL, NULL),
(6, 'O Hierofante', 5, 'V', NULL, FALSE, 'Tradição, aprendizado formal e orientação por regras ou instituições estabelecidas.', 4, NULL, NULL, NULL),
(7, 'Os Enamorados', 6, 'VI', 'R10', TRUE, 'Duas camadas que coexistem: união/conexão genuína (alinhamento real de valores) e escolha significativa — decisão consciente entre dois caminhos, que diz algo sobre quem a pessoa é.', 4, NULL, NULL, NULL),
(8, 'O Carro', 7, 'VII', NULL, FALSE, 'Vontade direcionada, vitória por foco e disciplina — avançar apesar de forças opostas.', 1, NULL, NULL, NULL),
(9, 'A Força', 8, 'VIII', 'R11', TRUE, 'Coragem genuína exercida com compaixão e autocontrole, não com força bruta — domar o instinto com paciência interior, poder que vem da serenidade.', 1, NULL, NULL, 'conquistado com esforço interno consciente'),
(10, 'O Eremita', 9, 'IX', NULL, FALSE, 'Introspecção e busca interior — necessidade de se retirar para refletir antes de agir.', 4, NULL, NULL, NULL),
(11, 'A Roda da Fortuna', 10, 'X', 'R12', TRUE, 'O ciclo inevitável da vida — sorte, destino e mudança fora do controle direto da pessoa. O que sobe, desce; o que desce, sobe. Convida a soltar a ilusão de controle total.', 2, NULL, NULL, NULL),
(12, 'A Justiça', 11, 'XI', 'R13', TRUE, 'Equilíbrio, verdade e causa-efeito: decisões justas baseadas em fatos, não em emoção. O que foi plantado será colhido, com clareza.', 1, 'HISTORICO_SOLIDO', 3, NULL),
(13, 'O Enforcado', 12, 'XII', NULL, FALSE, 'Pausa forçada, ver a situação de outro ângulo, rendição necessária antes de agir.', 2, NULL, NULL, NULL),
(14, 'A Morte', 13, 'XIII', 'R14', TRUE, 'Não é morte física — é transformação profunda e encerramento simbólico de um ciclo que já cumpriu sua função, abrindo espaço obrigatório para o novo.', 3, NULL, NULL, 'transição já madura'),
(15, 'A Temperança', 14, 'XIV', 'R15', TRUE, 'Equilíbrio, moderação e integração de opostos (como as duas taças misturando líquidos). Cura gradual, ajuste fino, a arte do meio-termo certo, sem excessos.', 1, NULL, NULL, 'de forma gradual'),
(16, 'O Diabo', 15, 'XV', 'R16', TRUE, 'Aprisionamento autoimposto — vício, apego, dependência ou padrão tóxico que a pessoa poderia largar, mas ainda não se permite (as correntes, na carta clássica, são frouxas).', 3, NULL, NULL, 'de origem interna'),
(17, 'A Torre', 16, 'XVI', 'R17', TRUE, 'A ruptura inevitável — colapso súbito de uma estrutura já comprometida por dentro. Não cria a crise: revela uma que já existia, de forma abrupta e fora do controle da pessoa.', 3, NULL, NULL, NULL),
(18, 'A Estrela', 17, 'XVII', 'R18', TRUE, 'Esperança, cura e renovação depois de uma crise — a serenidade que sucede o colapso da Torre. Fé no futuro e reconexão consigo mesmo, sem a euforia do Sol.', 1, NULL, NULL, 'de forma suave, sem euforia'),
(19, 'A Lua', 18, 'XVIII', NULL, FALSE, 'Ilusão, confusão e medos inconscientes — intuição turva, cuidado para não se guiar por aparências.', 2, NULL, NULL, NULL),
(20, 'O Sol', 19, 'XIX', 'R19', TRUE, 'Vitalidade, sucesso, clareza e alegria genuína — a carta mais próxima de um "sim" direto do baralho. Verdade exposta à luz, reconhecimento e vitória sem ambiguidade.', 1, NULL, NULL, NULL),
(21, 'O Julgamento', 20, 'XX', NULL, FALSE, 'Despertar, chamado para uma nova fase, avaliação final de um ciclo que se encerra.', 3, NULL, NULL, NULL),
(22, 'O Mundo', 21, 'XXI', 'R20', TRUE, 'Conclusão e realização plena — um ciclo inteiro completado com sucesso. É a última carta da jornada do Louco: integração total, sensação de "chegar lá".', 1, NULL, NULL, NULL);
INSERT INTO significado (carta_id, ambito_id, posicao_id, texto) VALUES
(1, 1, 1, 'Pessoa sem muita experiência afetiva; contexto pede iniciar a jornada para ganhar vivência.'),
(1, 2, 1, 'Pessoa sem muita experiência no cargo/mercado; está construindo a bagagem, não usando uma já existente.'),
(1, 3, 1, 'Estudante iniciante numa área/matéria nova, ainda sem método consolidado.'),
(1, 1, 2, 'É preciso se expor emocionalmente sem garantias para a relação avançar.'),
(1, 2, 2, 'Pede decisão de arriscar (aceitar proposta, trocar de emprego) mesmo sem certeza do resultado.'),
(1, 3, 2, 'Pede mudar de abordagem de estudo ou tentar algo novo mesmo sem garantia de sucesso.'),
(1, 1, 3, 'Não é carta natural de Resultado; se aparecer, indica começo inesperado e rota sem garantias.'),
(1, 2, 3, 'Novo começo que só se revela depois da decisão tomada.'),
(1, 3, 3, 'Necessidade de dar o salto rumo ao desconhecido.'),
(2, 1, 1, 'Pessoa com clareza sobre o que quer e capacidade de agir para conquistar/construir isso.'),
(2, 2, 1, 'Pessoa com as habilidades e recursos necessários em mãos, na posição de tomar iniciativa.'),
(2, 3, 1, 'Estudante com domínio das ferramentas necessárias (método, recursos); só falta aplicar.'),
(2, 1, 2, 'Uma ação decisiva e focada está sendo tomada na relação.'),
(2, 2, 2, 'Momento de transformar intenção em ação concreta no trabalho.'),
(2, 3, 2, 'Momento de aplicar o método/recurso que já se domina.'),
(2, 1, 3, 'Manifestação bem-sucedida daquilo que foi intencionado na relação.'),
(2, 2, 3, 'A vontade se concretiza em resultado profissional visível.'),
(2, 3, 3, 'Domínio do conteúdo se confirma no resultado.'),
(3, 1, 1, 'Pessoa guiada pela intuição, possivelmente guardando sentimentos ainda não verbalizados.'),
(3, 2, 1, 'Pessoa com percepção estratégica que ainda não expôs abertamente; boa fase para observar antes de agir.'),
(3, 3, 1, 'Estudante com compreensão intuitiva de um assunto, mesmo sem conseguir formalizar esse conhecimento ainda.'),
(3, 1, 2, 'Momento pede escuta interna e paciência, não ação impulsiva.'),
(3, 2, 2, 'Pede observação estratégica antes de qualquer movimento público.'),
(3, 3, 2, 'Pede deixar a compreensão amadurecer antes de tentar explicá-la/prová-la.'),
(3, 1, 3, 'A verdade afetiva se revela com o tempo, não por força.'),
(3, 2, 3, 'A resposta profissional certa depende de confiar no processo interno.'),
(3, 3, 3, 'O entendimento se consolida com paciência, não com pressa.'),
(7, 1, 1, 'Pessoa diante de uma decisão afetiva importante, ou vivendo conexão de valores genuína com alguém.'),
(7, 2, 1, 'Pessoa diante de uma escolha de carreira relevante, que reflete valores, não só conveniência.'),
(7, 3, 1, 'Estudante decidindo entre dois caminhos de formação que precisam refletir o que realmente importa.'),
(7, 1, 2, 'Uma decisão afetiva está amadurecendo e não dá para adiar para sempre.'),
(7, 2, 2, 'Uma escolha de carreira está se aproximando, exigindo posicionamento.'),
(7, 3, 2, 'Uma decisão sobre rumo de estudos está se formando.'),
(7, 1, 3, 'Escolha consciente que consolida (ou encerra) o vínculo com clareza.'),
(7, 2, 3, 'Decisão de carreira bem alinhada aos valores, mesmo que difícil.'),
(7, 3, 3, 'Definição clara de um caminho de formação que faz sentido.'),
(9, 1, 1, 'Pessoa lidando com desafio afetivo com paciência e compaixão, não confronto impulsivo.'),
(9, 2, 1, 'Pessoa enfrentando desafio de trabalho com resiliência e controle emocional.'),
(9, 3, 1, 'Estudante superando dificuldade com disciplina e paciência, não com virada de última hora.'),
(9, 1, 2, 'A situação pede domar um impulso (raiva, medo) com calma, não reagir no automático.'),
(9, 2, 2, 'Pede resiliência frente a um obstáculo de trabalho.'),
(9, 3, 2, 'Pede constância e disciplina em vez de esforço explosivo e pontual.'),
(9, 1, 3, 'Superação de um desafio afetivo pela via da paciência.'),
(9, 2, 3, 'Vitória profissional que vem de dentro, do autocontrole.'),
(9, 3, 3, 'Domínio da matéria conquistado por disciplina consistente.'),
(11, 1, 1, 'Pessoa numa fase afetiva marcada por reviravoltas externas.'),
(11, 2, 1, 'Pessoa numa fase de carreira sujeita a fatores fora do seu controle (mercado, timing, decisões de terceiros).'),
(11, 3, 1, 'Estudante numa fase de altos e baixos que dependem também de fatores externos (sorte, timing).'),
(11, 1, 2, 'Mudança de ciclo em curso, movida por fatores externos.'),
(11, 2, 2, 'Virada de carreira em curso, fora do controle direto.'),
(11, 3, 2, 'Virada de fase de estudos em curso, por fatores externos.'),
(11, 1, 3, 'Desfecho depende de fatores fora do controle total — pode ser bom, mas é incerto até se concretizar.'),
(11, 2, 3, 'Desfecho profissional depende de fatores fora do controle total — recomenda-se estar preparado para os dois lados.'),
(11, 3, 3, 'Desfecho acadêmico depende de fatores fora do controle total — pode ser bom, mas é incerto até se concretizar.'),
(12, 1, 1, 'Situação que exige honestidade e equilíbrio nas decisões afetivas.'),
(12, 2, 1, 'Pessoa diante de uma avaliação justa (mérito, contrato, decisão formal) baseada em fatos.'),
(12, 3, 1, 'Estudante diante de uma avaliação que vai refletir exatamente o esforço/preparo real.'),
(12, 1, 2, 'Uma decisão afetiva está sendo processada com base em fatos reais.'),
(12, 2, 2, 'Uma avaliação/processo está em curso e tende a ser justo, desde que a pessoa também seja honesta.'),
(12, 3, 2, 'Um processo avaliativo em curso, proporcional ao esforço já investido.'),
(12, 1, 3, 'Resultado proporcional ao mérito/esforço real na relação.'),
(12, 2, 3, 'Resultado profissional proporcional ao mérito — sem distorções.'),
(12, 3, 3, 'Nota/resultado que reflete exatamente o preparo real.'),
(14, 1, 1, 'Fim de uma fase afetiva (não necessariamente da relação em si, mas de uma forma antiga de se relacionar).'),
(14, 2, 1, 'Fase de carreira que já se esgotou — o cargo ou modo de trabalhar não cabe mais em quem a pessoa se tornou.'),
(14, 3, 1, 'Fase de estudos/abordagem que não serve mais; é preciso deixar um método ou área para evoluir.'),
(14, 1, 2, 'Um encerramento está em curso — uma forma antiga do vínculo está morrendo para uma nova nascer.'),
(14, 2, 2, 'Uma transição de carreira ou função está se processando.'),
(14, 3, 2, 'Uma virada de chave em curso: o jeito antigo de estudar está sendo substituído.'),
(14, 1, 3, 'Transformação definitiva — fim real da relação ou de uma versão antiga dela, sem volta ao que era.'),
(14, 2, 3, 'Fechamento de um ciclo profissional como ponto de virada necessário.'),
(14, 3, 3, 'Encerramento de uma fase de formação — o antes e o depois ficam claramente separados.'),
(15, 1, 1, 'Pessoa buscando (ou precisando buscar) equilíbrio e paciência no relacionamento.'),
(15, 2, 1, 'Pessoa em fase de ajuste no trabalho — moderação entre exigência e descanso.'),
(15, 3, 1, 'Estudante buscando equilíbrio entre estudo e descanso, ajustando método aos poucos.'),
(15, 1, 2, 'Processo gradual de ajuste e integração em curso na relação.'),
(15, 2, 2, 'Ajuste gradual de rotina/expectativas no trabalho em curso.'),
(15, 3, 2, 'Ajuste gradual de método de estudo em curso.'),
(15, 1, 3, 'Equilíbrio alcançado com paciência — harmonia sustentável no tempo.'),
(15, 2, 3, 'Sucesso gradual, conquistado por ajuste, não por golpe único.'),
(15, 3, 3, 'Domínio construído aos poucos, de forma sustentável.'),
(16, 1, 1, 'Pessoa presa a um padrão pouco saudável — dependência emocional, ciúme, relação desequilibrada de poder.'),
(16, 2, 1, 'Pessoa presa a uma situação de trabalho tóxica ou a um padrão próprio (procrastinação, medo de sair da zona de conforto).'),
(16, 3, 1, 'Estudante preso a um padrão prejudicial (procrastinação, comparação excessiva, medo de errar).'),
(16, 1, 2, 'Um padrão de apego/dependência está se intensificando na relação.'),
(16, 2, 2, 'Um padrão prejudicial está se intensificando no trabalho.'),
(16, 3, 2, 'Um padrão prejudicial está travando o progresso nos estudos.'),
(16, 1, 3, 'Se nada mudar, o desfecho é permanecer presa ao padrão — a corrente não se rompe sozinha.'),
(16, 2, 3, 'Se nada mudar, o desfecho é permanecer presa ao padrão no trabalho — a corrente não se rompe sozinha.'),
(16, 3, 3, 'Se nada mudar, o desfecho é permanecer presa ao padrão nos estudos — a corrente não se rompe sozinha.'),
(17, 1, 1, 'Relação sobre base frágil (segredo, desalinhamento, dependência) prestes a ser exposta.'),
(17, 2, 1, 'Situação de trabalho instável mesmo que pareça estável por fora.'),
(17, 3, 1, 'Método de estudo ou situação acadêmica insustentável que vai cobrar a conta.'),
(17, 1, 2, 'Ruptura ou confronto em curso e não dá para evitar.'),
(17, 2, 2, 'Mudança abrupta em andamento: corte, demissão, reestruturação.'),
(17, 3, 2, 'Crise em curso: reprovação se formando, choque de realidade sobre o método.'),
(17, 1, 3, 'Fim de um ciclo afetivo como está; o que resta depois tende a ser mais verdadeiro.'),
(17, 2, 3, 'Desfecho de perda/corte que remove algo sem sustentação, abrindo espaço para reconstrução.'),
(17, 3, 3, 'Resultado de reprovação ou necessidade de recomeçar o método.'),
(18, 1, 1, 'Pessoa em processo de cura emocional após fase difícil, reconectando com esperança.'),
(18, 2, 1, 'Pessoa se recuperando de fase profissional difícil, reencontrando inspiração e propósito.'),
(18, 3, 1, 'Estudante recuperando confiança após dificuldade, reconectando com o motivo original de estudar.'),
(18, 1, 2, 'Processo de cura e renovação em curso, de melhora gradual.'),
(18, 2, 2, 'Processo de recuperação e renovação profissional em curso, de melhora gradual.'),
(18, 3, 2, 'Processo de recuperação e renovação nos estudos em curso, de melhora gradual.'),
(18, 1, 3, 'Esperança realizada — recomeço genuíno e mais saudável, mesmo que não perfeito.'),
(18, 2, 3, 'Recomeço profissional mais saudável que o ponto de partida.'),
(18, 3, 3, 'Recomeço de formação mais consciente e saudável.'),
(20, 1, 1, 'Pessoa em fase de leveza afetiva, autoestima alta, relação transparente.'),
(20, 2, 1, 'Pessoa em momento de reconhecimento, confiança e energia produtiva.'),
(20, 3, 1, 'Estudante em fase de confiança e clareza — entendimento "acendeu".'),
(20, 1, 2, 'Relação caminha para mais abertura e verdade.'),
(20, 2, 2, 'As coisas se encaminham para reconhecimento profissional.'),
(20, 3, 2, 'Entendimento se consolidando, destravando uma dificuldade.'),
(20, 1, 3, 'Desfecho feliz e verdadeiro — reconciliação sincera, confiança mútua.'),
(20, 2, 3, 'Sucesso visível: aprovação, conquista, resultado reconhecido publicamente.'),
(20, 3, 3, 'Aprovação, boa nota, domínio real da matéria.'),
(22, 1, 1, 'Fase de relacionamento completo e realizado, ou fechamento de ciclo afetivo importante.'),
(22, 2, 1, 'Colheita dos frutos de um ciclo de trabalho bem conduzido.'),
(22, 3, 1, 'Conclusão de uma etapa de formação com sucesso, sensação de missão cumprida.'),
(22, 1, 2, 'Um ciclo afetivo está se completando, aproximando-se de um fechamento bem-sucedido.'),
(22, 2, 2, 'Um ciclo profissional está se completando com sucesso.'),
(22, 3, 2, 'Uma etapa de formação está se completando com sucesso.'),
(22, 1, 3, 'Conclusão plena e satisfatória do ciclo afetivo.'),
(22, 2, 3, 'Objetivo profissional perseguido se realiza de forma completa e reconhecida.'),
(22, 3, 3, 'Formação/etapa concluída de forma completa e reconhecida.');
INSERT INTO regra (codigo_regra, tipo, descricao, prioridade, condicao_json, categoria_resultado_id, herda_categoria_de, texto, texto_complemento, fonte) VALUES
('R21', 'COMPOSTA', 'SE O Louco em Movimento E O Sol em Resultado ENTÃO categoria final = Favorável, novo começo com desfecho positivo.', 9, '{"todas": [{"posicao": ["Movimento"], "carta_em": ["O Louco"]}, {"posicao": ["Resultado"], "carta_em": ["O Sol"]}]}', 1, NULL, 'Novo começo com desfecho positivo, reforçando o resultado Favorável.', 'novo começo com desfecho positivo', 'R21 (Seção 8.2), fichas 9.3.1 e 9.3.13'),
('R22', 'COMPOSTA', 'SE O Louco na tiragem E A Torre na tiragem ENTÃO categoria final = Cautela / Adiar, cautela redobrada antes de se lançar.', 5, '{"todas": [{"carta_em": ["O Louco"]}, {"carta_em": ["A Torre"]}]}', 2, NULL, 'Cautela redobrada: melhor avaliar onde "vai cair" antes de se lançar.', 'cautela redobrada antes de se lançar', 'R22 (Seção 8.2), fichas 9.3.1 e 9.3.11'),
('R23', 'COMPOSTA', 'SE A Torre em Movimento E O Sol em Resultado ENTÃO categoria final = Mudança Necessária, tendência positiva após a mudança.', 1, '{"todas": [{"posicao": ["Movimento"], "carta_em": ["A Torre"]}, {"posicao": ["Resultado"], "carta_em": ["O Sol"]}]}', 3, NULL, 'Ruptura necessária seguida de desfecho favorável e claro.', 'tendência positiva após a mudança', 'R23 (Seção 8.2) e Seção 9.5'),
('R24', 'COMPOSTA', 'SE O Diabo na tiragem E A Estrela na tiragem ENTÃO categoria final = Mudança Necessária, de origem interna, com tendência de cura.', 3, '{"todas": [{"carta_em": ["O Diabo"]}, {"carta_em": ["A Estrela"]}]}', 3, NULL, 'Reconhecer o apego é o primeiro passo para a cura e a libertação real.', 'de origem interna, com tendência de cura', 'R24 (Seção 8.2), fichas 9.3.10 e 9.3.12'),
('R25', 'COMPOSTA', 'SE Os Enamorados na tiragem E O Diabo na tiragem ENTÃO categoria final = Cautela / Adiar, reavaliar a decisão antes de agir.', 6, '{"todas": [{"carta_em": ["Os Enamorados"]}, {"carta_em": ["O Diabo"]}]}', 2, NULL, 'Alerta: a decisão pode estar sendo tomada por apego ou medo, não por valor genuíno — reavaliar antes de decidir.', 'reavaliar a decisão antes de agir', 'R25 (Seção 8.2), fichas 9.3.4 e 9.3.10'),
('R30', 'COMPOSTA', 'SE A Torre ou A Morte na tiragem E O Sol ou A Estrela na tiragem ENTÃO categoria final = Mudança Necessária, tendência positiva após a mudança.', 2, '{"todas": [{"carta_em": ["A Torre", "A Morte"]}, {"carta_em": ["O Sol", "A Estrela"]}]}', 3, NULL, 'Ruptura ou transformação que desemboca em clareza, esperança e cura.', 'tendência positiva após a mudança', 'Fichas 9.3.8 (Morte + Sol, Morte + Estrela), 9.3.11 (Torre + Estrela) e 9.3.12'),
('R31', 'COMPOSTA', 'SE A Roda da Fortuna na tiragem E carta com categoria Favorável na tiragem ENTÃO categoria final = Favorável, a virada de ciclo tende para o lado bom.', 11, '{"todas": [{"carta_em": ["A Roda da Fortuna"]}, {"categoria_em": ["FAVORAVEL"]}]}', 1, NULL, 'Com uma carta de apoio favorável, a virada de ciclo tende para o lado bom.', 'a virada de ciclo tende para o lado bom', 'Ficha 9.3.6 (Roda + Sol) e Seção 8.3 (Roda sem carta de apoio favorável = Cautela)'),
